--   N°            -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE           -> dt_datearrivee et dt_datecourier
--   prénom + NOM   -> txt_prenomNom et txt_expediteur
--   OBJET          -> txt_objet, puis txt_designation et txt_categorie
--   TF             -> txt_numTitreFoncier
--   LOT            -> txt_numLot
--   AGENTS         -> txt_agenttraiteur
--   OBSERVATIONS   -> txt_observation
